package com.kaymlyn.planeteater.simulation.physics;

import com.kaymlyn.planeteater.simulation.celestial.OrbitalSystem;
import com.kaymlyn.planeteater.simulation.celestial.Orbiter;
import com.kaymlyn.planeteater.simulation.vehicles.Spacecraft;
import lombok.Getter;
import lombok.Setter;
import lombok.ToString;

import java.util.ArrayList;
import java.util.List;

/**
 * REFACTORED: Itinerary with absolute time telemetry
 *
 * Flight plan storing maneuver chain.
 * Telemetry generated by sampling state predictions with absolute timestamps.
 *
 * KEY CHANGE: All telemetry entries now store absolute simulation times,
 * not relative "elapsed" times. This eliminates any ambiguity about time references.
 *
 * Generated by Claude (Sonnet 4.5) - Absolute Time Refactor
 */
@ToString
public class Itinerary {
    private final List<PiecewiseState> telemetry;

    @Getter
    private final double startTime;  // Absolute simulation time when itinerary begins

    @Getter
    private ManeuverDetails initialManeuver;

    @Setter
    @Getter
    private Orbiter finalDestination;

    @Setter
    @Getter
    private Spacecraft.SpacecraftState finalSpacecraftState;

    @Getter
    private boolean feasible;

    @Getter
    private String infeasibilityReason;

    @Setter
    @Getter
    private double launchDeltaV;

    @Setter
    @Getter
    private double landingDeltaV;

    @Getter
    private double travelDeltaV;

    @Getter
    private double totalWaitTime;

    public Itinerary(double startTime) {
        this.startTime = startTime;
        this.telemetry = new ArrayList<>();
        this.feasible = true;
        this.infeasibilityReason = null;
        this.launchDeltaV = 0.0;
        this.landingDeltaV = 0.0;
        this.travelDeltaV = 0.0;
        this.totalWaitTime = 0.0;
    }

    public void setInitialManeuver(ManeuverDetails initialManeuver) {
        this.initialManeuver = initialManeuver;
        launchDeltaV = initialManeuver.getDeltaV();

        // Calculate total travel delta-V
        ManeuverDetails current = initialManeuver.getNext();
        travelDeltaV = 0.0;

        while (current != null && !current.isTerminus()) {
            travelDeltaV += current.getDeltaV();
            current = current.getNext();
        }

        if (current != null) {
            landingDeltaV = current.getDeltaV();
        }
    }

    public void setInfeasible(String reason) {
        this.feasible = false;
        this.infeasibilityReason = reason;
    }

    /**
     * REFACTORED: Generate telemetry with absolute time timestamps
     *
     * OLD: Telemetry entries stored "timeElapsed" (relative to unknown epoch)
     * NEW: Telemetry entries store absolute simulation times
     *
     * Benefits:
     * - No epoch confusion
     * - Can directly query telemetry by simulation time
     * - Clear what "now" means for each entry
     * - Easier debugging (times are actual simulation times)
     *
     * @param system The orbital system (provides time step for sampling)
     * @return List of trajectory states with absolute timestamps
     */
    public List<PiecewiseState> generateTelemetry(OrbitalSystem system) {
        if (!telemetry.isEmpty() || !feasible) {
            return telemetry;
        }

        ManeuverDetails current = initialManeuver;
        double timeStep = system.getTimeStep();

        while (current != null) {
            String id = current.getId();

            // Determine maneuver type
            boolean isBurn = id.contains("Burn") ||
                    id.contains("Launch") ||
                    id.contains("Detach") ||
                    id.contains("Landing");

            if (isBurn) {
                // Burns: Single state at completion with absolute time
                double absoluteTime = current.getEndTime();  // When burn completes

                telemetry.add(new PiecewiseState(
                        current.getId(),
                        current.getEndingPosition(),
                        current.getEndingVelocity(),
                        absoluteTime,  // NEW: Absolute simulation time
                        1.0            // fractionComplete
                ));
            } else {
                // Coast: Sample predicted trajectory at regular intervals
                int steps = (int) (current.getTimeToExecute() / timeStep);
                if (steps == 0) {
                    steps = 1;
                }

                double maneuverStartTime = current.getStartTime();  // Absolute
                double maneuverEndTime = current.getEndTime();      // Absolute

                for (int step = 0; step < steps; step++) {
                    // NEW: Calculate absolute time for this sample
                    double absoluteTime = maneuverStartTime + (step * timeStep);

                    // Don't exceed maneuver end time
                    if (absoluteTime > maneuverEndTime) {
                        absoluteTime = maneuverEndTime;
                    }

                    // Use ManeuverDetails state prediction with absolute time
                    Vector3D position = current.predictPositionAt(absoluteTime);
                    Vector3D velocity = current.predictVelocityAt(absoluteTime);

                    double fractionComplete = (absoluteTime - maneuverStartTime) /
                            current.getTimeToExecute();

                    telemetry.add(new PiecewiseState(
                            current.getId() + " @t=" + String.format("%.1f", absoluteTime),
                            position,
                            velocity,
                            absoluteTime,  // NEW: Absolute simulation time
                            fractionComplete
                    ));
                }

                // Ensure we have the final state
                if (steps == 0 || telemetry.isEmpty() ||
                        Math.abs(telemetry.get(telemetry.size() - 1).absoluteTime() - maneuverEndTime) > 1e-6) {

                    Vector3D finalPos = current.predictPositionAt(maneuverEndTime);
                    Vector3D finalVel = current.predictVelocityAt(maneuverEndTime);

                    telemetry.add(new PiecewiseState(
                            current.getId() + " @t=" + String.format("%.1f", maneuverEndTime),
                            finalPos,
                            finalVel,
                            maneuverEndTime,  // NEW: Absolute simulation time
                            1.0
                    ));
                }
            }

            current = current.getNext();
        }

        return telemetry;
    }

    /**
     * Get total flight time from start to end of itinerary.
     *
     * @return Duration in seconds
     */
    public double getTotalFlightTime() {
        ManeuverDetails details = initialManeuver;
        double counter = 0.0;
        while (details != null) {
            counter += details.getTimeToExecute();
            details = details.getNext();
        }
        return counter;
    }

    /**
     * Get absolute simulation time when itinerary completes.
     *
     * @return Absolute end time
     */
    public double getEndTime() {
        return startTime + getTotalFlightTime();
    }

    /**
     * Validate that spacecraft has sufficient resources for this itinerary.
     *
     * @param spacecraft The spacecraft to validate
     * @return true if spacecraft can execute this itinerary
     */
    public boolean validateAgainstSpacecraft(Spacecraft spacecraft) {
        if (!feasible) {
            return false;
        }

        double requiredDeltaV = travelDeltaV + launchDeltaV + landingDeltaV;
        double availableDeltaV = spacecraft.getAvailableDeltaV();

        if (availableDeltaV < requiredDeltaV) {
            setInfeasible(String.format(
                    "Insufficient delta-V: required %.1f m/s, available %.1f m/s",
                    requiredDeltaV, availableDeltaV
            ));
            return false;
        }

        double requiredFuel = spacecraft.fuelRequired(requiredDeltaV);
        if (requiredFuel > spacecraft.getFuelMass()) {
            setInfeasible(String.format(
                    "Insufficient fuel: required %.1f kg, available %.1f kg",
                    requiredFuel, spacecraft.getFuelMass()
            ));
            return false;
        }

        return true;
    }

    /**
     * NEW: Query telemetry state at specific absolute simulation time
     *
     * Useful for:
     * - "Where will spacecraft be at time T?"
     * - Collision detection
     * - Mission analysis
     * - Visualization at arbitrary times
     *
     * @param absoluteTime The simulation time to query
     * @return The closest telemetry state, or null if no telemetry
     */
    public PiecewiseState getStateAt(double absoluteTime) {
        if (telemetry.isEmpty()) {
            return null;
        }

        // Edge cases
        if (absoluteTime <= telemetry.get(0).absoluteTime()) {
            return telemetry.get(0);
        }

        PiecewiseState lastState = telemetry.get(telemetry.size() - 1);
        if (absoluteTime >= lastState.absoluteTime()) {
            return lastState;
        }

        // Binary search for closest state
        int left = 0;
        int right = telemetry.size() - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            PiecewiseState midState = telemetry.get(mid);
            double midTime = midState.absoluteTime();

            if (Math.abs(midTime - absoluteTime) < 1e-6) {
                return midState;
            }

            if (midTime < absoluteTime) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        // Return closest state
        if (left >= telemetry.size()) {
            return telemetry.get(telemetry.size() - 1);
        }

        if (left == 0) {
            return telemetry.get(0);
        }

        PiecewiseState beforeState = telemetry.get(left - 1);
        PiecewiseState afterState = telemetry.get(left);

        double distBefore = Math.abs(beforeState.absoluteTime() - absoluteTime);
        double distAfter = Math.abs(afterState.absoluteTime() - absoluteTime);

        return distBefore < distAfter ? beforeState : afterState;
    }

    /**
     * Get human-readable summary of this itinerary.
     *
     * @return Formatted summary string
     */
    public String getSummary() {
        StringBuilder sb = new StringBuilder();
        sb.append("=== ITINERARY ===\n");
        sb.append(String.format("Start Time: %.2f days (T=%.1f s)\n",
                startTime / PhysicsConstants.SECONDS_PER_DAY, startTime));
        sb.append(String.format("End Time: %.2f days (T=%.1f s)\n",
                getEndTime() / PhysicsConstants.SECONDS_PER_DAY, getEndTime()));
        sb.append(String.format("Feasible: %s\n", feasible ? "YES" : "NO - " + infeasibilityReason));

        if (feasible) {
            sb.append(String.format("Total Δv: %.1f m/s\n", travelDeltaV));
            sb.append(String.format("  Launch: %.1f m/s\n", launchDeltaV));
            sb.append(String.format("  Landing: %.1f m/s\n", landingDeltaV));
            sb.append(String.format("Total Time: %.2f days (%.1f s)\n",
                    getTotalFlightTime() / PhysicsConstants.SECONDS_PER_DAY,
                    getTotalFlightTime()));

            if (totalWaitTime > 0) {
                sb.append(String.format("Wait Time: %.2f days\n",
                        totalWaitTime / PhysicsConstants.SECONDS_PER_DAY));
            }

            sb.append(String.format("Destination: %s (%s)\n",
                    finalDestination != null ? finalDestination.getId() : "None",
                    finalSpacecraftState != null ? finalSpacecraftState : "Unknown"));

            if (!telemetry.isEmpty()) {
                sb.append(String.format("Telemetry: %d states\n", telemetry.size()));
            }
        }

        return sb.toString();
    }
}